<?php $pageTitle='Mis cursos';$pageSubtitle='Consulta los cursos que tienes asignados y continúa tu aprendizaje.';require __DIR__.'/../partials/header.php'; ?><div class="grid"><?php foreach($c as $x): ?><div class="card course-card"><div class="course-image">Curso</div><h3><?=htmlspecialchars($x['titulo_curso'])?></h3><p><?=htmlspecialchars($x['descripcion_curso'])?></p><div class="progress"><span style="width:<?=min(100,(float)$x['avance'])?>%"></span></div><div class="meta"><span><?=htmlspecialchars($x['avance'])?>% completado</span><span><?=htmlspecialchars($x['instructor'])?></span></div><a class="btn btn-primary" href="index.php?route=curso&id=<?=$x['id_curso_c_a']?>">Continuar</a></div><?php endforeach; ?><?php if(!$c): ?><div class="empty">No tienes cursos asignados.</div><?php endif; ?></div><?php require __DIR__.'/../partials/footer.php'; ?>
